package org.millenaire.common.village;import java.util.*;import org.millenaire.common.utilities.Point;import org.millenaire.common.entity.MillVillager;public class Building{public static class Resources{public Point harvest;public Point getSnailSoilHarvestLocation(){return harvest;}public int getNbSnailSoilHarvestLocation(){return harvest==null?0:1;}}public Resources resources=new Resources();public int dyeStock;public List<Building> farms=new ArrayList<>();public List<MillVillager> villagers=new ArrayList<>();public Resources getResManager(){return resources;}public List<Building> getBuildingsWithTag(String s){return farms;}public Point getPos(){return resources.harvest;}public int nbGoodAvailable(org.millenaire.common.item.InvItem i,boolean a,boolean b,boolean c){if(i.item()!=net.minecraft.world.item.Items.PURPLE_DYE||i.meta()!=0)throw new AssertionError("Wrong inventory key");return dyeStock;}public List<MillVillager> getKnownVillagers(){return villagers;}}